  ('21cfcb80-7211-5c7c-b8bc-727b0e13b5a5', null, (select id from public.skills where slug = 'write-g11-precise-language'), null, 'medium',
   $q$Read the sentence: "At this point in time, the observatory is in the process of upgrading its telescope." Which revision is the most concise?$q$, $q$[{"text":"The observatory is currently upgrading its telescope.","is_correct":true},{"text":"The observatory upgraded its telescope.","is_correct":false,"misconception_token":"wrong-tense"},{"text":"At this point in time, the observatory is upgrading its telescope.","is_correct":false,"misconception_token":"wordy-phrase-remains"},{"text":"Currently, at present, the observatory is upgrading its telescope.","is_correct":false,"misconception_token":"redundancy"}]$q$::jsonb, $q$The observatory is currently upgrading its telescope.$q$, $q$"Currently" replaces "at this point in time," and "is upgrading" replaces "is in the process of upgrading." "The observatory upgraded its telescope" is shorter but says the work is already finished.$q$, 'draft', null)
