  ('a45bb154-5c86-5449-bac1-f55ba44fece3', null, (select id from public.skills where slug = 'write-g11-precise-language'), null, 'medium',
   $q$Read the sentence: "The marathon route, which is twenty-six miles long in length, passes through four neighborhoods." Which revision is the most concise without losing information?$q$, $q$[{"text":"The marathon route, twenty-six miles long in length, passes through four neighborhoods.","is_correct":false,"misconception_token":"redundancy-remains"},{"text":"The twenty-six-mile marathon route passes through four neighborhoods.","is_correct":true},{"text":"The marathon route, which in length measures twenty-six miles long, passes through four neighborhoods.","is_correct":false,"misconception_token":"wordy"},{"text":"The marathon route, which is long, passes through four neighborhoods.","is_correct":false,"misconception_token":"drops-detail"}]$q$::jsonb, $q$The twenty-six-mile marathon route passes through four neighborhoods.$q$, $q$"Long" already refers to length, so "in length" is redundant, and the measurement fits neatly before the noun. "The marathon route, twenty-six miles long in length" cuts "which is" but keeps "long in length."$q$, 'draft', null)
