  ('1b31066f-a2a1-5640-8327-05dc271c2c8c', null, (select id from public.skills where slug = 'write-g11-precise-language'), null, 'hard',
   $q$Read the sentence: "The implementation of the plan resulted in a reduction in the consumption of energy by the school." Which revision is the most precise and concise?$q$, $q$[{"text":"Implementing the plan reduced the school's energy consumption.","is_correct":true},{"text":"The plan's implementation resulted in a reduction of the school's energy consumption.","is_correct":false,"misconception_token":"nominalization-remains"},{"text":"The plan reduced energy.","is_correct":false,"misconception_token":"drops-detail"},{"text":"The school implemented the plan, resulting in a reduction in consumption of energy.","is_correct":false,"misconception_token":"wordy"}]$q$::jsonb, $q$Implementing the plan reduced the school's energy consumption.$q$, $q$Turning "implementation" and "reduction" into verbs removes the chain of "of" phrases while keeping every fact. "The plan's implementation resulted in a reduction" is shorter but still buries the action in nouns.$q$, 'draft', null)
