  ('d554d4e0-3f06-5be2-bc97-003805b1a642', null, (select id from public.skills where slug = 'write-g11-precise-language'), null, 'hard',
   $q$Read the sentences: "The satellite's battery was failing. Engineers shut down its camera. They wanted to save power for the radio." Which revision shows the relationships among the ideas most precisely?$q$, $q$[{"text":"The satellite's battery was failing, so engineers shut down its camera, and they wanted to save power for the radio.","is_correct":false,"misconception_token":"loose-coordination"},{"text":"Although the satellite's battery was failing, engineers shut down its camera to save power for the radio.","is_correct":false,"misconception_token":"wrong-relationship"},{"text":"Engineers shut down the camera, the battery was failing, they saved power for the radio.","is_correct":false,"misconception_token":"comma-splice"},{"text":"Because the satellite's battery was failing, engineers shut down its camera to save power for the radio.","is_correct":true}]$q$::jsonb, $q$Because the satellite's battery was failing, engineers shut down its camera to save power for the radio.$q$, $q$"Because" marks the cause and "to save power" marks the purpose, so each link is clear. The "so ... and" version is grammatical but treats the purpose as a separate, loosely added fact.$q$, 'draft', null)
