  ('13148c1f-ae80-5cf5-af46-62d2bb85b0a2', null, (select id from public.skills where slug = 'write-g11-sentence-structure'), null, 'medium',
   $q$Read the sentence: "Scanning the night sky with the new telescope, a faint comet appeared near the horizon." Which revision fixes the dangling modifier?$q$, $q$[{"text":"A faint comet, scanning the night sky with the new telescope, appeared near the horizon.","is_correct":false,"misconception_token":"misplaced-modifier"},{"text":"Scanning the night sky with the new telescope, the horizon showed a faint comet.","is_correct":false,"misconception_token":"dangling-modifier-shifted"},{"text":"Scanning the night sky with the new telescope, a faint comet was seen near the horizon.","is_correct":false,"misconception_token":"dangling-modifier-unfixed"},{"text":"Scanning the night sky with the new telescope, Imani spotted a faint comet near the horizon.","is_correct":true}]$q$::jsonb, $q$Scanning the night sky with the new telescope, Imani spotted a faint comet near the horizon.$q$, $q$The opening phrase describes someone scanning the sky, so the subject right after it must be that person, Imani. Making the verb passive still leaves the comet as the subject, so the comet still seems to be doing the scanning.$q$, 'draft', null)
