  ('20131f16-63d2-5ffd-b582-fe4769641d33', null, (select id from public.skills where slug = 'write-g11-sentence-structure'), null, 'medium',
   $q$Read the sentences: "Dr. Okafor studies a rare fungus. One that glows faintly in the dark forests of the island." Which revision fixes the fragment?$q$, $q$[{"text":"Dr. Okafor studies a rare fungus, one that glows faintly in the dark forests of the island.","is_correct":true},{"text":"Dr. Okafor studies a rare fungus; one that glows faintly in the dark forests of the island.","is_correct":false,"misconception_token":"semicolon-before-phrase"},{"text":"Dr. Okafor studies a rare fungus. Which glows faintly in the dark forests of the island.","is_correct":false,"misconception_token":"fragment-unfixed"},{"text":"Dr. Okafor studies a rare fungus, it glows faintly in the dark forests of the island.","is_correct":false,"misconception_token":"comma-splice-created"}]$q$::jsonb, $q$Dr. Okafor studies a rare fungus, one that glows faintly in the dark forests of the island.$q$, $q$"One that glows faintly..." is an appositive that renames the fungus, so it joins the main clause with a comma. Changing it to "it glows" creates an independent clause, and a comma alone cannot join two independent clauses.$q$, 'draft', null)
