  ('4a74620d-3be7-529a-a51d-cd5369c53d78', null, (select id from public.skills where slug = 'write-g11-sentence-structure'), null, 'medium',
   $q$Read the sentence: "The new recycling program aims not only to reduce waste ___." Which choice completes the sentence with correct parallel structure?$q$, $q$[{"text":"and also the town's disposal costs will be lower","is_correct":false,"misconception_token":"correlative-pair-broken"},{"text":"but also lowering the town's disposal costs","is_correct":false,"misconception_token":"faulty-parallelism-gerund"},{"text":"but also to lower the town's disposal costs","is_correct":true},{"text":"but it also lowers the town's disposal costs","is_correct":false,"misconception_token":"faulty-correlative-clause"}]$q$::jsonb, $q$but also to lower the town's disposal costs$q$, $q$"Not only" is followed by the infinitive "to reduce," so "but also" must be followed by another infinitive, "to lower." The "lowering" choice keeps the correct conjunction pair but switches to a gerund.$q$, 'draft', null)
