  ('b6076c9e-b72a-555d-b261-71c4e6575405', null, (select id from public.skills where slug = 'write-g11-sentence-structure'), null, 'medium',
   $q$Read the sentence: "To qualify for the state chess tournament, at least five rated games must be completed." Which revision fixes the dangling modifier?$q$, $q$[{"text":"To qualify for the state chess tournament, a player must complete at least five rated games.","is_correct":true},{"text":"At least five rated games, to qualify for the state chess tournament, must be completed.","is_correct":false,"misconception_token":"misplaced-modifier"},{"text":"To qualify for the state chess tournament, five rated games must be completed at least.","is_correct":false,"misconception_token":"dangling-modifier-unfixed"},{"text":"To qualify for the state chess tournament, completing at least five rated games is required.","is_correct":false,"misconception_token":"dangling-modifier-shifted"}]$q$::jsonb, $q$To qualify for the state chess tournament, a player must complete at least five rated games.$q$, $q$Only a person can qualify for a tournament, so the subject after the introductory phrase must be "a player." Making "completing" the subject still leaves no one to do the qualifying.$q$, 'draft', null)
