  ('0210a158-46a2-5c45-ac35-37026dea235a', null, (select id from public.skills where slug = 'write-g12-narrative-writing'), null, 'hard',
   $q$Which revision of sentence 12 best signals both the shift in setting and the narrator's renewed effort?$q$, $q$[{"text":"Afterward, we moved somewhere else in the creek and tried one more time.","is_correct":false,"misconception_token":"vague-setting"},{"text":"Meanwhile, other pairs of students were also using nets in the creek.","is_correct":false,"misconception_token":"shifts-focus-from-narrator"},{"text":"Twenty feet upstream, where the current quickened, we planted the net and kicked harder.","is_correct":true},{"text":"We moved and tried again, because the first sample had not gone very well.","is_correct":false,"misconception_token":"cause-without-setting"}]$q$::jsonb, $q$Twenty feet upstream, where the current quickened, we planted the net and kicked harder.$q$, $q$The correct choice names the new location precisely and shows the narrator working harder, which leads into the full tray. The choice with "Afterward" marks a shift but leaves the new setting vague.$q$, 'draft', '45ab10b5-fea1-5c1f-9c7a-06ea5df02e70')
